/** Signing and verifying the public catalog: Ed25519 over the catalog's canonical JSON.
 *
 * Canonical JSON is the catalog with object keys sorted at every level and no whitespace,
 * so the signer and every verifier hash the same bytes whatever order a JSON library wrote
 * the keys in. The private key never leaves the publisher (see scripts/sign-local-catalog.mjs);
 * readers hold only public keys, so the catalog can be served by anyone and trusted by
 * checking it. Several public keys may be trusted at once, so a key can be rotated. */

import { createHash, createPrivateKey, createPublicKey, sign, verify, type KeyObject } from 'node:crypto';
import { parseLocalCatalog, type LocalCatalog } from './catalog-schema.js';

export interface CatalogSignature {
  algorithm: 'ed25519';
  /** Which trusted key signed it: the first 16 hex characters of SHA-256 of the raw public key. */
  keyId: string;
  /** Base64 Ed25519 signature over canonicalJson(catalog). */
  value: string;
}

export interface SignedLocalCatalog {
  catalog: LocalCatalog;
  signature: CatalogSignature;
}

/** A public key a reader trusts: the raw 32 bytes, base64. */
export interface TrustedCatalogKey {
  keyId: string;
  publicKey: string;
}

/** ASN.1 prefix that wraps a raw 32-byte Ed25519 public key as SPKI DER. */
const SPKI_PREFIX = Buffer.from('302a300506032b6570032100', 'hex');

export function canonicalJson(value: unknown): string {
  if (value === null || typeof value === 'string' || typeof value === 'boolean') return JSON.stringify(value);
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new Error('Canonical JSON cannot hold a non-finite number.');
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) return `[${value.map((item) => canonicalJson(item)).join(',')}]`;
  if (typeof value === 'object') {
    const entries = Object.entries(value as Record<string, unknown>)
      .filter(([, item]) => item !== undefined)
      .sort(([left], [right]) => (left < right ? -1 : left > right ? 1 : 0));
    return `{${entries.map(([key, item]) => `${JSON.stringify(key)}:${canonicalJson(item)}`).join(',')}}`;
  }
  throw new Error(`Canonical JSON cannot hold a ${typeof value}.`);
}

function rawPublicKey(key: KeyObject): Buffer {
  return (key.export({ type: 'spki', format: 'der' }) as Buffer).subarray(SPKI_PREFIX.length);
}

export function catalogKeyId(publicKey: string): string {
  return createHash('sha256').update(Buffer.from(publicKey, 'base64')).digest('hex').slice(0, 16);
}

/** The public half of a private key (PKCS#8 PEM), as a trusted-key entry. */
export function trustedKeyFrom(privateKeyPem: string): TrustedCatalogKey {
  const publicKey = rawPublicKey(createPublicKey(createPrivateKey(privateKeyPem))).toString('base64');
  return { keyId: catalogKeyId(publicKey), publicKey };
}

export function signLocalCatalog(catalog: LocalCatalog, privateKeyPem: string): SignedLocalCatalog {
  parseLocalCatalog(catalog);
  const key = createPrivateKey(privateKeyPem);
  if (key.asymmetricKeyType !== 'ed25519') throw new Error('The catalog signing key must be an Ed25519 key.');
  return {
    catalog,
    signature: {
      algorithm: 'ed25519',
      keyId: trustedKeyFrom(privateKeyPem).keyId,
      value: sign(null, Buffer.from(canonicalJson(catalog)), key).toString('base64'),
    },
  };
}

/** The catalog inside a signed document, once its signature checks out against a trusted
 * key and its contents are a well-formed catalog. Throws otherwise: an unsigned, wrongly
 * signed, tampered or malformed document is never partly used. */
export function verifySignedCatalog(document: unknown, trusted: readonly TrustedCatalogKey[]): LocalCatalog {
  if (typeof document !== 'object' || document === null) throw new Error('The model catalog is not an object.');
  const { catalog, signature } = document as Partial<SignedLocalCatalog>;
  if (!signature || signature.algorithm !== 'ed25519' || typeof signature.value !== 'string' || typeof signature.keyId !== 'string') {
    throw new Error('The model catalog carries no Ed25519 signature.');
  }
  const key = trusted.find((candidate) => candidate.keyId === signature.keyId);
  if (!key) throw new Error(`The model catalog is signed by an unknown key (${signature.keyId}).`);
  const publicKey = createPublicKey({ key: Buffer.concat([SPKI_PREFIX, Buffer.from(key.publicKey, 'base64')]), format: 'der', type: 'spki' });
  // The signature covers what was published, fields this reader does not know included.
  if (!verify(null, Buffer.from(canonicalJson(catalog)), publicKey, Buffer.from(signature.value, 'base64'))) {
    throw new Error('The model catalog signature does not match its contents.');
  }
  return parseLocalCatalog(catalog);
}
